(1966322, 270363, 27533, '<td valign="top">This is a good image, but I feel it could have been better if the lashes closer to the camera were in focus.</td>', 'This is a good image, but I feel it could have been better if the lashes closer to the camera were in focus.', '2005-12-21 00:17:16.000000', NULL, 1),
(1966333, 271338, 27533, '<td valign="top">I like your title for this image.</td>', 'I like your title for this image.', '2005-12-21 00:20:11.000000', NULL, 1),
(1966341, 271371, 15711, '<td valign="top">Beautiful and interesting. I like the rich tones that are subtle yet impactful. Really pretty !!</td>', 'Beautiful and interesting. I like the rich tones that are subtle yet impactful. Really pretty !!', '2005-12-21 00:21:34.000000', NULL, 1),
(1966345, 270524, 15711, '<td valign="top">I love the Christmas tree lit shot. I think I''d prefer that the ornament (subject) not be so dead centered.  Lovely DOF and the colors are stunning.</td>', 'I love the Christmas tree lit shot. I think I''d prefer that the ornament (subject) not be so dead centered.  Lovely DOF and the colors are stunning.', '2005-12-21 00:22:53.000000', NULL, 1),
(1966346, 269535, 37961, '<td valign="top">Really nice entry. I love the way you set this up. 7 for now.</td>', 'Really nice entry. I love the way you set this up. 7 for now.', '2005-12-21 00:22:53.000000', NULL, 1),
(1966363, 271165, 47487, '<td valign="top">I like your composition. However, it''s not so much the depth of field as it is the lighting that makes your subject stand out.</td>', 'I like your composition. However, it''s not so much the depth of field as it is the lighting that makes your subject stand out.', '2005-12-21 00:27:48.000000', NULL, 1),
(1966365, 271045, 29906, '<td valign="top">I don''t see much of a depth of field here, but great photo.</td>', 'I don''t see much of a depth of field here, but great photo.', '2005-12-21 00:28:55.000000', NULL, 1),
(1966368, 270505, 47487, '<td valign="top">This is beautiful -- composition, light, setup, everything. However, I''m not sure the depth of field is shallow; the entire rose looks to be in focus, and the background is black. GORGEOUS image, but since it''s a technical challenge I feel like I shouldn''t give this the 9 or 10 it would otherwise deserve. 7.</td>', 'This is beautiful -- composition, light, setup, everything. However, I''m not sure the depth of field is shallow; the entire rose looks to be in focus, and the background is black. GORGEOUS image, but since it''s a technical challenge I feel like I shouldn''t give this the 9 or 10 it would otherwise deserve. 7.', '2005-12-21 00:30:10.000000', NULL, 1),
(1966373, 270722, 14212, '<td valign="top">definitely one of the winners. 10</td>', 'definitely one of the winners. 10', '2005-12-21 00:31:27.000000', NULL, 1),
(1966374, 270251, 32893, '<td valign="top">Nice shot.  Losing a little focus on the right side but not bad at all!</td>', 'Nice shot.  Losing a little focus on the right side but not bad at all!', '2005-12-21 00:31:27.000000', NULL, 1),
(1966380, 271086, 32893, '<td valign="top">Would like to see just a bit more DOF through the eyes.<br/> <br/>Still, good image!</td>', 'Would like to see just a bit more DOF through the eyes. Still, good image!', '2005-12-21 00:32:49.000000', NULL, 1),
