(1968099, 271086, 35804, '<td valign="top">Love those whiskers! The critter looks like he means business too! Very nice.</td>', 'Love those whiskers! The critter looks like he means business too! Very nice.', '2005-12-21 12:57:53.000000', NULL, 1),
(1968101, 269193, 35804, '<td valign="top">Really nice reds...lush and deep...very nice.</td>', 'Really nice reds...lush and deep...very nice.', '2005-12-21 12:58:34.000000', NULL, 1),
(1968104, 271086, 47378, '<td valign="top">Definitely a good shallow DOF shot, but it might have been more effective to focus on the eyes instead of the nose. Just a thought...</td>', 'Definitely a good shallow DOF shot, but it might have been more effective to focus on the eyes instead of the nose. Just a thought...', '2005-12-21 13:00:50.000000', NULL, 1),
(1968111, 270179, 47487, '<td valign="top">This is a pretty image, but unfortunately, even though the dof is shallow, your subject gets lost in the lights behind it.</td>', 'This is a pretty image, but unfortunately, even though the dof is shallow, your subject gets lost in the lights behind it.', '2005-12-21 13:06:08.000000', NULL, 1),
(1968118, 269094, 47487, '<td valign="top">ehh, I''m torn. You do have a shallow depth of field here, but then you went and desaturated selectively as well, which almost takes away from the effect of the shallow dof and turns it into an effect of selective desaturation. I do like the image very much, just trying to decide if the selective desat is kind of a cheap shot (but very effective, visually.). OK. Giving this an 8 because it is such a compelling image and you did meet the challenge criteria.</td>', 'ehh, I''m torn. You do have a shallow depth of field here, but then you went and desaturated selectively as well, which almost takes away from the effect of the shallow dof and turns it into an effect of selective desaturation. I do like the image very much, just trying to decide if the selective desat is kind of a cheap shot (but very effective, visually.). OK. Giving this an 8 because it is such a compelling image and you did meet the challenge criteria.', '2005-12-21 13:08:34.000000', NULL, 1),
(1968121, 269222, 47487, '<td valign="top">Good picture; would have been more effective, I think, if the focus was on the ball, but I respect your right to make your own artistic focus decisions. :)</td>', 'Good picture; would have been more effective, I think, if the focus was on the ball, but I respect your right to make your own artistic focus decisions. :)', '2005-12-21 13:09:49.000000', NULL, 1),
