(1969649, 271225, 4793, '<td valign="top">Nice shot</td>', 'Nice shot', '2005-12-21 22:12:10.000000', NULL, 1),
(1969651, 269970, 41522, '<td valign="top">I really like what you were trying to do here.  I think I would have liked to have seen the reason for the ime in the freground instead of the table.  JMO</td>', 'I really like what you were trying to do here.  I think I would have liked to have seen the reason for the ime in the freground instead of the table.  JMO', '2005-12-21 22:13:03.000000', NULL, 1),
(1969652, 269966, 4793, '<td valign="top">Nice comp and colors</td>', 'Nice comp and colors', '2005-12-21 22:13:07.000000', NULL, 1),
(1969655, 270722, 4793, '<td valign="top">Nice comp</td>', 'Nice comp', '2005-12-21 22:13:49.000000', NULL, 1),
(1969656, 271059, 4793, '<td valign="top">Beautiful colors, nice dof</td>', 'Beautiful colors, nice dof', '2005-12-21 22:14:29.000000', NULL, 1),
(1969658, 271149, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2005-12-21 22:15:24.000000', NULL, 1),
(1969659, 271334, 41522, '<td valign="top">Cool idea.  I would have liked a little more focus on the eyes.  For me, the eyes sort of come out creepy looking rather than the frustration of another lost button.  JMO</td>', 'Cool idea.  I would have liked a little more focus on the eyes.  For me, the eyes sort of come out creepy looking rather than the frustration of another lost button.  JMO', '2005-12-21 22:15:42.000000', NULL, 1),
(1969660, 270845, 4793, '<td valign="top">Nice holiday colors</td>', 'Nice holiday colors', '2005-12-21 22:16:27.000000', NULL, 1),
(1969661, 271325, 4793, '<td valign="top">Nice colors, comp and dof</td>', 'Nice colors, comp and dof', '2005-12-21 22:16:54.000000', NULL, 1),
(1969662, 269792, 4793, '<td valign="top">Nice tones and dof</td>', 'Nice tones and dof', '2005-12-21 22:17:19.000000', NULL, 1),
(1969665, 270998, 4793, '<td valign="top">Nice christmas shot</td>', 'Nice christmas shot', '2005-12-21 22:18:35.000000', NULL, 1),
(1969666, 270747, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2005-12-21 22:18:49.000000', NULL, 1),
(1969669, 270876, 4793, '<td valign="top">Interesting comp, good dof</td>', 'Interesting comp, good dof', '2005-12-21 22:20:08.000000', NULL, 1),
(1969671, 270993, 4793, '<td valign="top">Beautiful colors</td>', 'Beautiful colors', '2005-12-21 22:20:33.000000', NULL, 1),
