(1970096, 269505, 23913, '<td valign="top">very well lite nice colors (sat.) i like the image alot...good use of DoF</td>', 'very well lite nice colors (sat.) i like the image alot...good use of DoF', '2005-12-22 00:52:57.000000', NULL, 1),
(1970105, 269384, 40019, '<td valign="top">Great picture - beautiful beetle!  I would have liked a little more focus/detail on the beetle and less on the hand - but very nicely done anyway!</td>', 'Great picture - beautiful beetle!  I would have liked a little more focus/detail on the beetle and less on the hand - but very nicely done anyway!', '2005-12-22 00:54:49.000000', NULL, 1),
(1970111, 271266, 40019, '<td valign="top">I like the picture.  Very nicely executed and meets the challenge perfectly - great colors and detail.  Just not very original.</td>', 'I like the picture.  Very nicely executed and meets the challenge perfectly - great colors and detail.  Just not very original.', '2005-12-22 00:56:33.000000', NULL, 1),
(1970133, 271045, 40019, '<td valign="top">Great picture.  Great lighting and detail in the eye.  I would have liked more DOF. Even the hair back by the ear is in focus.</td>', 'Great picture.  Great lighting and detail in the eye.  I would have liked more DOF. Even the hair back by the ear is in focus.', '2005-12-22 01:02:44.000000', NULL, 1),
(1970137, 269110, 43031, '<td valign="top">thank you for your pretty diversion from the challenge.</td>', 'thank you for your pretty diversion from the challenge.', '2005-12-22 01:03:41.000000', NULL, 1),
(1970140, 269891, 40019, '<td valign="top">I like the colors and texture, but I''m not sure where the focal point is.  It all looks a little blurry - I''m looking for the crisp, in focus part of the picture - it''s just not jumping out at me.</td>', 'I like the colors and texture, but I''m not sure where the focal point is.  It all looks a little blurry - I''m looking for the crisp, in focus part of the picture - it''s just not jumping out at me.', '2005-12-22 01:04:35.000000', NULL, 1),
