(1970154, 270900, 23394, '<td valign="top">i hope to take a shot like this some day...</td>', 'i hope to take a shot like this some day...', '2005-12-22 01:07:27.000000', NULL, 1),
(1970500, 270900, 31443, '<td valign="top">Pity about the tip of her tail! Like your courage to show the female who is less colorful but she''s really beautiful, well done..</td>', 'Pity about the tip of her tail! Like your courage to show the female who is less colorful but she''s really beautiful, well done..', '2005-12-22 03:57:10.000000', NULL, 1),
