(1970528, 271039, 16046, '<td valign="top">Did you get a macro of the ice? You will find cool patterrns up real close.</td>', 'Did you get a macro of the ice? You will find cool patterrns up real close.', '2005-12-22 04:46:16.000000', NULL, 1),
(1970530, 270721, 16046, '<td valign="top">Awesome find.</td>', 'Awesome find.', '2005-12-22 04:48:36.000000', NULL, 1),
