(1970573, 271086, 49425, '<td valign="top">If you had made its eyes sharper instead of the nose I think it would have given it more visual appeal.</td>', 'If you had made its eyes sharper instead of the nose I think it would have given it more visual appeal.', '2005-12-22 06:00:37.000000', NULL, 1),
(1970576, 271277, 49425, '<td valign="top">Place the leader between the other pieces in focus... would have been better.</td>', 'Place the leader between the other pieces in focus... would have been better.', '2005-12-22 06:11:26.000000', NULL, 1),
