(1971422, 270564, 16950, '<td valign="top">Very simple, but still one of my favorites.  10</td>', 'Very simple, but still one of my favorites.  10', '2005-12-22 14:25:14.000000', NULL, 1),
(1971424, 270415, 32644, '<td valign="top">Beautiful example of the challenge. The fall colors really add to this sharp shot.</td>', 'Beautiful example of the challenge. The fall colors really add to this sharp shot.', '2005-12-22 14:25:27.000000', NULL, 1),
(1971426, 270456, 32644, '<td valign="top">Your composition of the out of focus lights really makes this shot. Nice job.</td>', 'Your composition of the out of focus lights really makes this shot. Nice job.', '2005-12-22 14:26:30.000000', NULL, 1),
(1971427, 270987, 28097, '<td valign="top">hehe.. right back atcha ... maybe if the shadow line came right in the middle of the wace.. would have contoured the face pretty nicely...  i like</td>', 'hehe.. right back atcha ... maybe if the shadow line came right in the middle of the wace.. would have contoured the face pretty nicely...  i like', '2005-12-22 14:26:43.000000', NULL, 1),
(1971429, 269229, 32644, '<td valign="top">This is great. I love the texture and color of this lizard. Very nice job.</td>', 'This is great. I love the texture and color of this lizard. Very nice job.', '2005-12-22 14:27:24.000000', NULL, 1),
(1971432, 271287, 45187, '<td valign="top">not shallow DOF</td>', 'not shallow DOF', '2005-12-22 14:28:55.000000', NULL, 1),
(1971434, 270747, 32644, '<td valign="top">This is so shallow, I don''t see anything in focus. It is an interesting shot, though.</td>', 'This is so shallow, I don''t see anything in focus. It is an interesting shot, though.', '2005-12-22 14:29:08.000000', NULL, 1),
(1971435, 271322, 28097, '<td valign="top">wow... i love the brownish match between the bird''s feather and the leaves int he background...  the bird stands right out of the picture thanx to DOF and color contrast... nice work...</td>', 'wow... i love the brownish match between the bird''s feather and the leaves int he background...  the bird stands right out of the picture thanx to DOF and color contrast... nice work...', '2005-12-22 14:29:53.000000', NULL, 1),
(1971439, 269943, 45187, '<td valign="top">leaf just not sharp enough for me to give this a GREAT score.</td>', 'leaf just not sharp enough for me to give this a GREAT score.', '2005-12-22 14:31:30.000000', NULL, 1),
(1971445, 269243, 28097, '<td valign="top">cute little thing</td>', 'cute little thing', '2005-12-22 14:34:05.000000', NULL, 1),
(1971482, 270320, 44490, '<td valign="top">Nice idea, try for an angle rather than straight on, with rule of thirds, not so centered.</td>', 'Nice idea, try for an angle rather than straight on, with rule of thirds, not so centered.', '2005-12-22 14:51:33.000000', NULL, 1),
(1971486, 269189, 44490, '<td valign="top">Beautiful photo, but DOF is not very shallow.  There''s some distracting noise, probably due to over processing.</td>', 'Beautiful photo, but DOF is not very shallow.  There''s some distracting noise, probably due to over processing.', '2005-12-22 14:55:26.000000', NULL, 1),
(1971491, 271038, 40386, '<td valign="top">The blow out on the ring spoils what would otherwise be a great idea and shot, maybe play with the highlights as the shirt in the background is also a bit bright. Well done and good luck.</td>', 'The blow out on the ring spoils what would otherwise be a great idea and shot, maybe play with the highlights as the shirt in the background is also a bit bright. Well done and good luck.', '2005-12-22 14:56:51.000000', NULL, 1),
(1971515, 271371, 29011, '<td valign="top">Beautiful shot! Though I would''ve preferred a totally dry glass to go with the theme.</td>', 'Beautiful shot! Though I would''ve preferred a totally dry glass to go with the theme.', '2005-12-22 15:06:17.000000', NULL, 1),
(1971527, 269105, 44490, '<td valign="top">Good arrangement, wish the highlights and reflections were toned down just a bit, but I like the image.</td>', 'Good arrangement, wish the highlights and reflections were toned down just a bit, but I like the image.', '2005-12-22 15:09:19.000000', NULL, 1),
(1971530, 271083, 44490, '<td valign="top">javascript: do_vote(4)</td>', 'javascript: do_vote(4)', '2005-12-22 15:10:37.000000', NULL, 1),
(1971532, 271373, 29011, '<td valign="top">pitty about the image quality, I really like this shot nonetheless :)</td>', 'pitty about the image quality, I really like this shot nonetheless :)', '2005-12-22 15:11:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1971538, 269958, 44490, '<td valign="top">Nice idea, tighter would probably be better.</td>', 'Nice idea, tighter would probably be better.', '2005-12-22 15:15:36.000000', NULL, 1),
(1971554, 269311, 49672, '<td valign="top">The right side is too bright, the left is too dark.</td>', 'The right side is too bright, the left is too dark.', '2005-12-22 15:22:21.000000', NULL, 1),
(1971557, 271110, 49672, '<td valign="top">I''m not too fond of the shadow, otherwise it is OK.</td>', 'I''m not too fond of the shadow, otherwise it is OK.', '2005-12-22 15:23:14.000000', NULL, 1),
(1971559, 271272, 49672, '<td valign="top">I''m pretty sure I don''t get it.</td>', 'I''m pretty sure I don''t get it.', '2005-12-22 15:23:40.000000', NULL, 1),
(1971562, 269846, 49672, '<td valign="top">I don''t like the blown highlights in the upper right.</td>', 'I don''t like the blown highlights in the upper right.', '2005-12-22 15:24:08.000000', NULL, 1),
(1971564, 270716, 49672, '<td valign="top">Cute cat, but it isn''t DOF that is highlighting your subject.</td>', 'Cute cat, but it isn''t DOF that is highlighting your subject.', '2005-12-22 15:24:39.000000', NULL, 1),
(1971565, 270993, 49672, '<td valign="top">Is this shallow DOF?  Lots of JPEG artifacts, too.</td>', 'Is this shallow DOF?  Lots of JPEG artifacts, too.', '2005-12-22 15:25:15.000000', NULL, 1),
(1971569, 270455, 49672, '<td valign="top">Too many blown highlights for me.</td>', 'Too many blown highlights for me.', '2005-12-22 15:25:43.000000', NULL, 1),
(1971571, 271287, 49672, '<td valign="top">Not sure that this is using DOF at all...</td>', 'Not sure that this is using DOF at all...', '2005-12-22 15:26:16.000000', NULL, 1),
(1971575, 270914, 49672, '<td valign="top">DOF is indeed shallow, subject isn''t too interesting.</td>', 'DOF is indeed shallow, subject isn''t too interesting.', '2005-12-22 15:27:26.000000', NULL, 1),
(1971576, 270631, 49672, '<td valign="top">A bit low in contrast, I think.  There is also a lot going on in the picture.</td>', 'A bit low in contrast, I think.  There is also a lot going on in the picture.', '2005-12-22 15:28:19.000000', NULL, 1),
(1971580, 269596, 49672, '<td valign="top">I would have liked the focus on the eyes better than the nose.</td>', 'I would have liked the focus on the eyes better than the nose.', '2005-12-22 15:29:05.000000', NULL, 1),
(1971583, 270126, 49672, '<td valign="top">Hard to tell the subject of the photo.</td>', 'Hard to tell the subject of the photo.', '2005-12-22 15:29:41.000000', NULL, 1),
(1971585, 270366, 49672, '<td valign="top">I would have liked the focus on the front of the bottle rather than on the side.</td>', 'I would have liked the focus on the front of the bottle rather than on the side.', '2005-12-22 15:30:18.000000', NULL, 1),
(1971586, 270921, 44490, '<td valign="top">Nice, beautiful capture.  DOF could be shallower for the challenge.</td>', 'Nice, beautiful capture.  DOF could be shallower for the challenge.', '2005-12-22 15:30:22.000000', NULL, 1),
(1971589, 271152, 49672, '<td valign="top">DOF isn''t very shallow, especially for the subject.</td>', 'DOF isn''t very shallow, especially for the subject.', '2005-12-22 15:31:06.000000', NULL, 1),
(1971591, 270825, 49706, '<td valign="top">4-glorious foreground, but the background is distracting. Maybe the dof is just not shallow enough.</td>', '4-glorious foreground, but the background is distracting. Maybe the dof is just not shallow enough.', '2005-12-22 15:31:52.000000', NULL, 1),
(1971592, 271335, 44490, '<td valign="top">Nice composition and colors.  DOF could be shallower for the challenge.</td>', 'Nice composition and colors.  DOF could be shallower for the challenge.', '2005-12-22 15:32:18.000000', NULL, 1),
(1971593, 269397, 49672, '<td valign="top">Harsh flash, not very shallow DOF.</td>', 'Harsh flash, not very shallow DOF.', '2005-12-22 15:32:25.000000', NULL, 1),
(1971597, 270799, 49672, '<td valign="top">Since the background is mostly white, it is hard to tell what the DOF is like.</td>', 'Since the background is mostly white, it is hard to tell what the DOF is like.', '2005-12-22 15:33:29.000000', NULL, 1),
(1971598, 270885, 49672, '<td valign="top">Seems out of focus, and the top corner is distracting.</td>', 'Seems out of focus, and the top corner is distracting.', '2005-12-22 15:33:55.000000', NULL, 1),
(1971599, 271225, 49672, '<td valign="top">This has a pretty deep DOF for the subject matter, IMO.  It is a wonderful photograph, however.</td>', 'This has a pretty deep DOF for the subject matter, IMO.  It is a wonderful photograph, however.', '2005-12-22 15:34:47.000000', NULL, 1),
(1971603, 270939, 49672, '<td valign="top">The lights in the background seem blown and the branch in the foreground is distracting.</td>', 'The lights in the background seem blown and the branch in the foreground is distracting.', '2005-12-22 15:35:32.000000', NULL, 1),
(1971605, 271057, 49672, '<td valign="top">The light sticking out of the corner is distracting to the overall picture.  I would have liked it cropped out, I think.</td>', 'The light sticking out of the corner is distracting to the overall picture.  I would have liked it cropped out, I think.', '2005-12-22 15:36:26.000000', NULL, 1),
(1971615, 271035, 49706, '<td valign="top">7- great shot, could use cropping on the top to the farthest blurred gull or just past the grassy area, and from the right to the closest blurred gull, maybe slight brightening and contrast</td>', '7- great shot, could use cropping on the top to the farthest blurred gull or just past the grassy area, and from the right to the closest blurred gull, maybe slight brightening and contrast', '2005-12-22 15:41:44.000000', NULL, 1),
(1971617, 270921, 43565, '<td valign="top">I like this shot, but it doesn''t seem to have a very shallow DOF.</td>', 'I like this shot, but it doesn''t seem to have a very shallow DOF.', '2005-12-22 15:44:09.000000', NULL, 1),
(1971620, 271086, 44490, '<td valign="top">Not bad for a pet shot, just a touch more DOF to include the eyes would help.</td>', 'Not bad for a pet shot, just a touch more DOF to include the eyes would help.', '2005-12-22 15:44:57.000000', NULL, 1),
(1971622, 269970, 43565, '<td valign="top">Since the child having a time out seems to be the subject, I think he/she should be what is in focus.</td>', 'Since the child having a time out seems to be the subject, I think he/she should be what is in focus.', '2005-12-22 15:46:16.000000', NULL, 1),
(1971633, 269260, 49706, '<td valign="top">7- beautiful leaf and drop, i like the light area at the top of the background; i suggest you crop a good deal on the right side</td>', '7- beautiful leaf and drop, i like the light area at the top of the background; i suggest you crop a good deal on the right side', '2005-12-22 15:49:39.000000', NULL, 1),
(1971636, 269792, 44490, '<td valign="top">Good idea and arrangement, just missing the thread through the needle, and maybe less central would be better.</td>', 'Good idea and arrangement, just missing the thread through the needle, and maybe less central would be better.', '2005-12-22 15:50:24.000000', NULL, 1),
(1971642, 270944, 49672, '<td valign="top">DOF is pretty deep for this subject.  Since the background is so dark, it is hard to tell what the exact DOF is...</td>', 'DOF is pretty deep for this subject.  Since the background is so dark, it is hard to tell what the exact DOF is...', '2005-12-22 15:52:21.000000', NULL, 1),
(1971643, 270426, 49706, '<td valign="top">7-aptly named with beautiful colors. I would maybe crop slightly at the bottom</td>', '7-aptly named with beautiful colors. I would maybe crop slightly at the bottom', '2005-12-22 15:52:34.000000', NULL, 1),
(1971646, 270939, 44490, '<td valign="top">Cute, nice composition for the bear, but the foreground foliage is distracting -- would be better if it were not obscuring the bear as much.</td>', 'Cute, nice composition for the bear, but the foreground foliage is distracting -- would be better if it were not obscuring the bear as much.', '2005-12-22 15:53:43.000000', NULL, 1),
(1971649, 269317, 7322, '<td valign="top">This could have been sharper around the rim of the spoon. I feel like the spoon could be looming a bit larger in the frame. This small, it lacks the boldness it takes to make a shot of an ordinary object really dynamic.  I like the nice soft blur of the handle in the distance and the pristine white background .</td>', 'This could have been sharper around the rim of the spoon. I feel like the spoon could be looming a bit larger in the frame. This small, it lacks the boldness it takes to make a shot of an ordinary object really dynamic.  I like the nice soft blur of the handle in the distance and the pristine white background .', '2005-12-22 15:54:46.000000', NULL, 1),
(1971651, 270608, 44490, '<td valign="top">Nice idea.  Closer/bigger/more-obvious hood ornament would probably be better.</td>', 'Nice idea.  Closer/bigger/more-obvious hood ornament would probably be better.', '2005-12-22 15:55:38.000000', NULL, 1),
(1971652, 271090, 49706, '<td valign="top">5-perhaps the road adds to the "forgotten" mood, but i find it distracting</td>', '5-perhaps the road adds to the "forgotten" mood, but i find it distracting', '2005-12-22 15:55:46.000000', NULL, 1),
(1971653, 271357, 49672, '<td valign="top">Since the bird takes up almost all of the picture, it is hard to tell the DOF.</td>', 'Since the bird takes up almost all of the picture, it is hard to tell the DOF.', '2005-12-22 15:56:17.000000', NULL, 1),
(1971655, 271114, 44490, '<td valign="top">Nice juxtaposition, just wish for more exposure.</td>', 'Nice juxtaposition, just wish for more exposure.', '2005-12-22 15:56:52.000000', NULL, 1),
(1971657, 269494, 49672, '<td valign="top">There seems to be haze/flare making the contrast too low.</td>', 'There seems to be haze/flare making the contrast too low.', '2005-12-22 15:57:08.000000', NULL, 1),
(1971658, 269222, 7322, '<td valign="top">I like the color and the pinball machine as subject matter but ultimately the blurred background looks more interesting to me than the foreground.</td>', 'I like the color and the pinball machine as subject matter but ultimately the blurred background looks more interesting to me than the foreground.', '2005-12-22 15:57:11.000000', NULL, 1),
(1971664, 270416, 49672, '<td valign="top">This is a tough subject for pleasing bokeh.  Your DOF is pretty shallow, though.</td>', 'This is a tough subject for pleasing bokeh.  Your DOF is pretty shallow, though.', '2005-12-22 15:57:59.000000', NULL, 1),
(1971667, 270505, 49706, '<td valign="top">9-quite possibly my favorite in this challenge. Might i suggest some of that beautiful lighting added to the center?</td>', '9-quite possibly my favorite in this challenge. Might i suggest some of that beautiful lighting added to the center?', '2005-12-22 15:58:14.000000', NULL, 1),
(1971668, 270297, 49672, '<td valign="top">This looks like a back-focus test chart.</td>', 'This looks like a back-focus test chart.', '2005-12-22 15:58:36.000000', NULL, 1),
(1971669, 270722, 31628, '<td valign="top">Instead of hammers, eh?  I like the concept, it could benefit from a little more post-processing.  Seems a bit raw and dingy still.</td>', 'Instead of hammers, eh?  I like the concept, it could benefit from a little more post-processing.  Seems a bit raw and dingy still.', '2005-12-22 15:58:47.000000', NULL, 1),
(1971674, 269856, 49672, '<td valign="top">This is a really good shot - the DOF keeps it interesting.</td>', 'This is a really good shot - the DOF keeps it interesting.', '2005-12-22 16:00:35.000000', NULL, 1),
(1971679, 270366, 44490, '<td valign="top">Nice colors, and reasonable composition, except the pipe(?) is distracting, would be better further back and in focus with the vial.</td>', 'Nice colors, and reasonable composition, except the pipe(?) is distracting, would be better further back and in focus with the vial.', '2005-12-22 16:02:48.000000', NULL, 1),
(1971683, 271213, 49672, '<td valign="top">Very shallow DOF, subject isn''t too interesting.</td>', 'Very shallow DOF, subject isn''t too interesting.', '2005-12-22 16:04:06.000000', NULL, 1),
(1971689, 270363, 49672, '<td valign="top">Wonderful shot.</td>', 'Wonderful shot.', '2005-12-22 16:04:46.000000', NULL, 1),
(1971690, 269968, 44490, '<td valign="top">One of the better figurine shots, good composition and colors.  Your photo really shows off shallow DOF - I love the star-like cactus geometry and the whole image.</td>', 'One of the better figurine shots, good composition and colors.  Your photo really shows off shallow DOF - I love the star-like cactus geometry and the whole image.', '2005-12-22 16:04:55.000000', NULL, 1),
(1971691, 271373, 49672, '<td valign="top">Great shot - seems heavy on the JPEG artifacts though.</td>', 'Great shot - seems heavy on the JPEG artifacts though.', '2005-12-22 16:05:38.000000', NULL, 1),
(1971693, 270722, 44490, '<td valign="top">Elegant and powerful idea, composition, and capture.  Well done.</td>', 'Elegant and powerful idea, composition, and capture.  Well done.', '2005-12-22 16:06:02.000000', NULL, 1),
(1971699, 270135, 44490, '<td valign="top">Nice composition, interesting, with a nice blend of in-focus and out-of-focus elements.  I like it.</td>', 'Nice composition, interesting, with a nice blend of in-focus and out-of-focus elements.  I like it.', '2005-12-22 16:07:23.000000', NULL, 1),
(1971703, 270947, 7322, '<td valign="top">A nice effort. I don''t quite understand your title. I think a colored card for the blurred background would have been more effective in adding some interest than then one that is shown here. The red ribbon in the front looks like a stab at framing and using color for contrast but I think the red would have been more effective in the background (as previously noted regarding the card). The ribbon isn''t quite framing the shot so much as adding a distracting element to the composition. The sphere of light created by the flame would have been a nice visual element as it echoes the curves on the rim of the bowl and the bowl itself, but it winds up competing for attention with the red and blue ribbons and the busy looking graphic on the card. I think eliminating the ribbons would have made this a much simpler, effective image. The size of this entry borders on being to small to effectively evaluate, for future reference.</td>', 'A nice effort. I don''t quite understand your title. I think a colored card for the blurred background would have been more effective in adding some interest than then one that is shown here. The red ribbon in the front looks like a stab at framing and using color for contrast but I think the red would have been more effective in the background (as previously noted regarding the card). The ribbon isn''t quite framing the shot so much as adding a distracting element to the composition. The sphere of light created by the flame would have been a nice visual element as it echoes the curves on the rim of the bowl and the bowl itself, but it winds up competing for attention with the red and blue ribbons and the busy looking graphic on the card. I think eliminating the ribbons would have made this a much simpler, effective image. The size of this entry borders on being to small to effectively evaluate, for future reference.', '2005-12-22 16:08:15.000000', NULL, 1),
(1971709, 270332, 31443, '<td valign="top">Love these colors</td>', 'Love these colors', '2005-12-22 16:11:09.000000', NULL, 1),
(1971710, 269094, 7322, '<td valign="top">This is kind of hokey for my taste and almost as a rule I hate selective desaturation, but I do like the background quite a bit. I like the the way the gates create a visual maze leading you in and out of the picture. I think I would have enjoyed this more without the dying flower and instead the focus being on the headstone.  The flower just interrupts my enjoyment of the background.</td>', 'This is kind of hokey for my taste and almost as a rule I hate selective desaturation, but I do like the background quite a bit. I like the the way the gates create a visual maze leading you in and out of the picture. I think I would have enjoyed this more without the dying flower and instead the focus being on the headstone.  The flower just interrupts my enjoyment of the background.', '2005-12-22 16:11:54.000000', NULL, 1),
(1971726, 269994, 7322, '<td valign="top">Interesting subject matter. The title confused me for a second. Ironically, this looks a bit dark to me. I think you could have turned the bottles (especially the third and fourth ones) to eliminate the bar codes which add a jarring square and colorless element to what could have been a very visually harmonious composition. I''m referring to the curvacious nature of the bottles, the Coke logo and the floral elements on the lables.</td>', 'Interesting subject matter. The title confused me for a second. Ironically, this looks a bit dark to me. I think you could have turned the bottles (especially the third and fourth ones) to eliminate the bar codes which add a jarring square and colorless element to what could have been a very visually harmonious composition. I''m referring to the curvacious nature of the bottles, the Coke logo and the floral elements on the lables.', '2005-12-22 16:18:33.000000', NULL, 1),
(1971730, 270595, 7322, '<td valign="top">Your title is silly but this is a nice picture of a squirrel.</td>', 'Your title is silly but this is a nice picture of a squirrel.', '2005-12-22 16:19:36.000000', NULL, 1),
(1971732, 269606, 42100, '<td valign="top">Very emotive photo with the tones and shadows.  Great job of putting more into your photo than just DOF.</td>', 'Very emotive photo with the tones and shadows.  Great job of putting more into your photo than just DOF.', '2005-12-22 16:20:22.000000', NULL, 1),
(1971736, 271110, 7322, '<td valign="top">Nice color and composition. I like that the curvy lines of the squirrel''s back and tail are echoed in the snow bank. The negative space is broken up very nicely. Very nice sharp detail on the squirrel.</td>', 'Nice color and composition. I like that the curvy lines of the squirrel''s back and tail are echoed in the snow bank. The negative space is broken up very nicely. Very nice sharp detail on the squirrel.', '2005-12-22 16:24:00.000000', NULL, 1),
(1971739, 270564, 7322, '<td valign="top">Very nice design. I really dislike the busy red border though.</td>', 'Very nice design. I really dislike the busy red border though.', '2005-12-22 16:25:04.000000', NULL, 1),
(1971748, 271089, 7322, '<td valign="top">I think you could have used a different background for the flowers than a wooden table top. The peachy colored background clashes with the violet. Pure white would have been more effective. I don''t like the black empty space at all. Maybe this could have been shot from a sharper angle? Good focus on the foreground flower.</td>', 'I think you could have used a different background for the flowers than a wooden table top. The peachy colored background clashes with the violet. Pure white would have been more effective. I don''t like the black empty space at all. Maybe this could have been shot from a sharper angle? Good focus on the foreground flower.', '2005-12-22 16:27:28.000000', NULL, 1),
(1971751, 271298, 7322, '<td valign="top">I just wish her ball wasn''t this hideous green thing. It doesn''t make for a compelling focal point and it completely dominates the image. The remainder is taken up by a distorted view of the dog''s nose, particularly her nostril.The ball is a rather noxious shade of green and it doesn''t harmonize well with the peachy, browns of the rest of the frame. The dog is really cute. I think in this case, focusing more on the dog (the interesting subject matter) and less on the ball would have worked. I would like to see the sparkle in the dog''s eyes, instead I am given a much closer view of her nostril than I care for.</td>', 'I just wish her ball wasn''t this hideous green thing. It doesn''t make for a compelling focal point and it completely dominates the image. The remainder is taken up by a distorted view of the dog''s nose, particularly her nostril.The ball is a rather noxious shade of green and it doesn''t harmonize well with the peachy, browns of the rest of the frame. The dog is really cute. I think in this case, focusing more on the dog (the interesting subject matter) and less on the ball would have worked. I would like to see the sparkle in the dog''s eyes, instead I am given a much closer view of her nostril than I care for.', '2005-12-22 16:33:30.000000', NULL, 1),
(1971753, 271214, 7322, '<td valign="top">A good idea but a more thoughtful arrangement of the pencils would make a better composition. This seems rather haphazard. There is a distracting shadow behind the pencil on the far left of the frame.</td>', 'A good idea but a more thoughtful arrangement of the pencils would make a better composition. This seems rather haphazard. There is a distracting shadow behind the pencil on the far left of the frame.', '2005-12-22 16:34:46.000000', NULL, 1),
(1971760, 270924, 7322, '<td valign="top">Perhaps if the image were bigger I would get more of a feeling of shalow DOF in this but at this size it is really difficult to see a major difference in the focus. I would not have placed the leaf against such a busy, similarly colored and textured background. It all looks like one flat brown mess to me. Sorry.</td>', 'Perhaps if the image were bigger I would get more of a feeling of shalow DOF in this but at this size it is really difficult to see a major difference in the focus. I would not have placed the leaf against such a busy, similarly colored and textured background. It all looks like one flat brown mess to me. Sorry.', '2005-12-22 16:37:58.000000', NULL, 1),
(1971767, 270825, 7322, '<td valign="top">Very pretty subject. The background is a bit busy, the various vertical and horizontal planes compete to much with the subject to really alow it to pop. A slightly diferent angle, elimnating the tree and that black and beige shape at the right of the frame would have helped a bit. Those two areas compete the most for my attention.</td>', 'Very pretty subject. The background is a bit busy, the various vertical and horizontal planes compete to much with the subject to really alow it to pop. A slightly diferent angle, elimnating the tree and that black and beige shape at the right of the frame would have helped a bit. Those two areas compete the most for my attention.', '2005-12-22 16:41:30.000000', NULL, 1),
