INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1972559, 270722, 26464, '<td valign="top">great idea, reminds me of pink floyd ''the wall'' with the walking hammers. i would have liked a more evenly lit foreground, but this is a 7 from me.</td>', 'great idea, reminds me of pink floyd ''the wall'' with the walking hammers. i would have liked a more evenly lit foreground, but this is a 7 from me.', '2005-12-22 22:22:16.000000', NULL, 1),
(1972567, 269057, 26464, '<td valign="top">very beautiful... love the fade-out of the flower.. forget anyone that says ''background not sharp enough'' 8<br/></td>', 'very beautiful... love the fade-out of the flower.. forget anyone that says ''background not sharp enough'' 8', '2005-12-22 22:24:42.000000', NULL, 1),
(1972571, 271346, 26464, '<td valign="top">bump the brightness up a bit to get the snow whiter<br/></td>', 'bump the brightness up a bit to get the snow whiter', '2005-12-22 22:25:50.000000', NULL, 1),
(1972573, 269231, 26464, '<td valign="top">would have been cool to get her drinking blood!!!<br/></td>', 'would have been cool to get her drinking blood!!!', '2005-12-22 22:26:14.000000', NULL, 1),
(1972576, 270466, 26464, '<td valign="top">nice sharpness.. i would have knocked the spidey webs off first<br/></td>', 'nice sharpness.. i would have knocked the spidey webs off first', '2005-12-22 22:26:51.000000', NULL, 1),
(1972593, 271338, 37105, '<td valign="top">I very much like the texture in the ''in focus'' section of this photograph. I know its a shallow DOF challenge, but this subject would benefit from a deeper DOF...</td>', 'I very much like the texture in the ''in focus'' section of this photograph. I know its a shallow DOF challenge, but this subject would benefit from a deeper DOF...', '2005-12-22 22:33:07.000000', NULL, 1),
(1972644, 270608, 28322, '<td valign="top">Niceeeeeeeeeeeeeeeeeeeeeee</td>', 'Niceeeeeeeeeeeeeeeeeeeeeee', '2005-12-22 22:48:07.000000', NULL, 1),
(1972653, 271038, 28322, '<td valign="top">How many Crt''s ? :) <br/>Nice ... Cheers,</td>', 'How many Crt''s ? :) Nice ... Cheers,', '2005-12-22 22:50:29.000000', NULL, 1),
(1972663, 269429, 28322, '<td valign="top">Nice idea, very well composed, cheers,</td>', 'Nice idea, very well composed, cheers,', '2005-12-22 22:53:28.000000', NULL, 1),
(1972681, 270987, 28322, '<td valign="top">How come!!</td>', 'How come!!', '2005-12-22 22:58:58.000000', NULL, 1),
(1972687, 270189, 48326, '<td valign="top">This picture would be much more flattering with softer light, away from the camera lens.</td>', 'This picture would be much more flattering with softer light, away from the camera lens.', '2005-12-22 23:04:24.000000', NULL, 1),
(1972753, 270508, 49672, '<td valign="top">Blown out highlights in the window are distracting  - they also led to an underexposed Homer.</td>', 'Blown out highlights in the window are distracting  - they also led to an underexposed Homer.', '2005-12-22 23:26:47.000000', NULL, 1),
(1972871, 270716, 17507, '<td valign="top">hopelessly cute! totally adorable.</td>', 'hopelessly cute! totally adorable.', '2005-12-22 23:56:19.000000', NULL, 1),
(1972942, 270380, 16241, '<td valign="top">nice!</td>', 'nice!', '2005-12-23 00:15:19.000000', NULL, 1),
(1972948, 271181, 16241, '<td valign="top">excellent for the challenge</td>', 'excellent for the challenge', '2005-12-23 00:16:38.000000', NULL, 1),
(1972951, 269384, 16241, '<td valign="top">very nice cuz!</td>', 'very nice cuz!', '2005-12-23 00:17:16.000000', NULL, 1),
(1972961, 269494, 37015, '<td valign="top">A slighter more shallow DOF would''ve helped this image.  However, because the length of the keys is so short, and it hits the face of the piano, there''s not much to see beyond the keys.  Maybe a shot more down the keyboard would''ve helped as well.</td>', 'A slighter more shallow DOF would''ve helped this image.  However, because the length of the keys is so short, and it hits the face of the piano, there''s not much to see beyond the keys.  Maybe a shot more down the keyboard would''ve helped as well.', '2005-12-23 00:20:43.000000', NULL, 1),
(1972963, 271377, 37015, '<td valign="top">DOF is not very apparent in this image.  However, it is nicely composed and the image is crisp.</td>', 'DOF is not very apparent in this image.  However, it is nicely composed and the image is crisp.', '2005-12-23 00:21:12.000000', NULL, 1),
(1972995, 269311, 45524, '<td valign="top">I like this composition and the colors, however the shadows and the blown out area on the the right really take away from the photo, try working with the lighting and see if the results are better. 5 from me</td>', 'I like this composition and the colors, however the shadows and the blown out area on the the right really take away from the photo, try working with the lighting and see if the results are better. 5 from me', '2005-12-23 00:30:34.000000', NULL, 1),
(1973026, 271086, 47852, '<td valign="top">Wow!  Love the expression, warm colors, perfectly focused nose, the whiskers... wonderful crop, and good use of a border.  A perfect 10!</td>', 'Wow!  Love the expression, warm colors, perfectly focused nose, the whiskers... wonderful crop, and good use of a border.  A perfect 10!', '2005-12-23 00:48:11.000000', NULL, 1),
(1973036, 271231, 47852, '<td valign="top">Going back through to add a few comments... I chose this one because when browsing the thumbnails I noticed the neat lines you captured with the dark trees and the icicles, and the way they sort of mirror each other.  But when I view the picture larger, I didn''t see the lines as much since the focus is on the ice (where it should be for this challenge).  I gave this one a 7... I think it''s just missing a little bit of that "Wow!" factor.</td>', 'Going back through to add a few comments... I chose this one because when browsing the thumbnails I noticed the neat lines you captured with the dark trees and the icicles, and the way they sort of mirror each other.  But when I view the picture larger, I didn''t see the lines as much since the focus is on the ice (where it should be for this challenge).  I gave this one a 7... I think it''s just missing a little bit of that "Wow!" factor.', '2005-12-23 00:52:36.000000', NULL, 1),
(1973055, 269317, 47852, '<td valign="top">Just going back to add some comments.  I like that you can see the texture in the fabric (?) that the spoon is resting on, as well as in the reflection... shows how shallow your DOF was.   I like a simple, clean shot with lots of negative space, but I think this one came out a bit too bright.</td>', 'Just going back to add some comments.  I like that you can see the texture in the fabric (?) that the spoon is resting on, as well as in the reflection... shows how shallow your DOF was.   I like a simple, clean shot with lots of negative space, but I think this one came out a bit too bright.', '2005-12-23 01:01:46.000000', NULL, 1),
(1973073, 271106, 47852, '<td valign="top">Just going back through to add some comments... <br/>Definately a shallow DOF!  I think I would have liked to see a bit more of the letter thats written above, and the signature part moved in to the middle of the paper.  You have captured just a tiny bit of the writing at the top, and the edge of the paper at the bottom, and I find both to be awkward.  Great idea... thanks for thinking beyond all of the plants and Christmas ornaments we''ve seen in this challenge!</td>', 'Just going back through to add some comments... Definately a shallow DOF!  I think I would have liked to see a bit more of the letter thats written above, and the signature part moved in to the middle of the paper.  You have captured just a tiny bit of the writing at the top, and the edge of the paper at the bottom, and I find both to be awkward.  Great idea... thanks for thinking beyond all of the plants and Christmas ornaments we''ve seen in this challenge!', '2005-12-23 01:07:52.000000', NULL, 1),
(1973093, 270845, 47852, '<td valign="top">Just coming back to add comments.<br/>I like the way the line of the garland flows around the picture and leads down to the lights.  I love the glow of the lights, but found the actual lights to be just a bit too bright.  It also appears as if the one bulb is burnt out.  I like the festive feel to this one, but in a challenge where we saw so many similar Christmas pics, I think it''s hard to stand out.</td>', 'Just coming back to add comments.I like the way the line of the garland flows around the picture and leads down to the lights.  I love the glow of the lights, but found the actual lights to be just a bit too bright.  It also appears as if the one bulb is burnt out.  I like the festive feel to this one, but in a challenge where we saw so many similar Christmas pics, I think it''s hard to stand out.', '2005-12-23 01:13:47.000000', NULL, 1),
(1973118, 269538, 47852, '<td valign="top">Just coming back to add comments...<br/>I usually think of these little candies as Halloween candy... so my first reaction to this shot after going through a ton of Christmas pictures was "Yay!  Some variety!"  I like the way you used the colors to bring out different parts of the candy... the white bottom to highlight the yellow, the orange middles to highlight the white tip of the front candy, and the blue background to highlight the rest of the white tips.  There''s something unsettling about a piece of candy corn THIS big though.  I don''t know if you could have achieved the same use of colors though without using a close setup like this though.  Nicely done.</td>', 'Just coming back to add comments...I usually think of these little candies as Halloween candy... so my first reaction to this shot after going through a ton of Christmas pictures was "Yay!  Some variety!"  I like the way you used the colors to bring out different parts of the candy... the white bottom to highlight the yellow, the orange middles to highlight the white tip of the front candy, and the blue background to highlight the rest of the white tips.  There''s something unsettling about a piece of candy corn THIS big though.  I don''t know if you could have achieved the same use of colors though without using a close setup like this though.  Nicely done.', '2005-12-23 01:20:56.000000', NULL, 1),
(1973132, 271149, 49706, '<td valign="top">9-this goes on my favorites... especially like the orange and blue</td>', '9-this goes on my favorites... especially like the orange and blue', '2005-12-23 01:26:21.000000', NULL, 1),
(1973148, 270598, 15511, '<td valign="top">A little more brightness, contrast &amp; saturation will remove the gray tint on the petals and make this image stand out. This is a beautiful flower.</td>', 'A little more brightness, contrast & saturation will remove the gray tint on the petals and make this image stand out. This is a beautiful flower.', '2005-12-23 01:33:03.000000', NULL, 1),
(1973255, 271336, 37893, '<td valign="top">I always keep coming back to this one. I gave you a 10. Who wouldn''t? It''s stunning and incredibly delicate not to mention probably hard to photograph.</td>', 'I always keep coming back to this one. I gave you a 10. Who wouldn''t? It''s stunning and incredibly delicate not to mention probably hard to photograph.', '2005-12-23 03:01:39.000000', NULL, 1),
(1973258, 271319, 37893, '<td valign="top">Beautiful Lion fish (?). The DOF is spot on in this image. I''m surprised you were able to get through to this little guy with no blur of motion at all :)</td>', 'Beautiful Lion fish (?). The DOF is spot on in this image. I''m surprised you were able to get through to this little guy with no blur of motion at all :)', '2005-12-23 03:02:40.000000', NULL, 1),
(1973263, 271360, 37893, '<td valign="top">Robert :) Your images are almost easily spotted from the crowd :) Great image. Is it just me or you used a glucose mix here because the dew drops are a bit cloudy and not as clear as your previous ones? Great image nevertheless. 8</td>', 'Robert :) Your images are almost easily spotted from the crowd :) Great image. Is it just me or you used a glucose mix here because the dew drops are a bit cloudy and not as clear as your previous ones? Great image nevertheless. 8', '2005-12-23 03:08:52.000000', NULL, 1),
(1973270, 269534, 37893, '<td valign="top">Lovely coloration and patterns :)</td>', 'Lovely coloration and patterns :)', '2005-12-23 03:17:28.000000', NULL, 1),
(1973271, 270434, 37893, '<td valign="top">Though the drops aren''t tack sharp, the refractions surely are. Great background wash as well.</td>', 'Though the drops aren''t tack sharp, the refractions surely are. Great background wash as well.', '2005-12-23 03:18:06.000000', NULL, 1),
(1973272, 270762, 37893, '<td valign="top">The starkness of this along with the message it sends out receives high makrs from me. I like the use of BW and the tonalities are excellent. 8</td>', 'The starkness of this along with the message it sends out receives high makrs from me. I like the use of BW and the tonalities are excellent. 8', '2005-12-23 03:18:52.000000', NULL, 1),
(1973273, 269917, 37893, '<td valign="top">Too bad the drop itself is a bit dark. The colors and the bulge are excellent though. Still gets an 8 from me ;)</td>', 'Too bad the drop itself is a bit dark. The colors and the bulge are excellent though. Still gets an 8 from me ;)', '2005-12-23 03:19:30.000000', NULL, 1),
