(1974584, 271334, 46885, '<td valign="top">How great! I was shooting something similar with my mom and it was a nightmare to catch her fingers, nevermind this mad look in the eyes! I would suggest only turning the needle a bit to see the eye of it.</td>', 'How great! I was shooting something similar with my mom and it was a nightmare to catch her fingers, nevermind this mad look in the eyes! I would suggest only turning the needle a bit to see the eye of it.', '2005-12-23 20:30:54.000000', NULL, 1),
(1974585, 269534, 11487, '<td valign="top">Great color, detail and composition.</td>', 'Great color, detail and composition.', '2005-12-23 20:31:57.000000', NULL, 1),
(1974586, 269211, 46885, '<td valign="top">Very good idea. I would make it a bit more centered and leave out the cellophane, although it does add a nice depth in the mid-bottom area.</td>', 'Very good idea. I would make it a bit more centered and leave out the cellophane, although it does add a nice depth in the mid-bottom area.', '2005-12-23 20:31:57.000000', NULL, 1),
(1974588, 271249, 11487, '<td valign="top">Very creative.  The color and pattern are great.</td>', 'Very creative.  The color and pattern are great.', '2005-12-23 20:32:43.000000', NULL, 1),
(1974589, 270900, 46885, '<td valign="top">Great colours but sharp areas look a bit questionable, the sharpness of the feathers doesn''t seem to agree with the areas of similar distance in the twigs/legs area. Where was the viewpoint?</td>', 'Great colours but sharp areas look a bit questionable, the sharpness of the feathers doesn''t seem to agree with the areas of similar distance in the twigs/legs area. Where was the viewpoint?', '2005-12-23 20:33:36.000000', NULL, 1),
(1974592, 271325, 46885, '<td valign="top">Good! I imagine the surrounding matryoshkas contesting the motherhood of this wee baby - their faces on the background seem to be so sulky!</td>', 'Good! I imagine the surrounding matryoshkas contesting the motherhood of this wee baby - their faces on the background seem to be so sulky!', '2005-12-23 20:35:08.000000', NULL, 1),
(1974594, 271376, 11487, '<td valign="top">Nice pattern.  The reflections on the part in focus is distracting.</td>', 'Nice pattern.  The reflections on the part in focus is distracting.', '2005-12-23 20:35:52.000000', NULL, 1),
(1974595, 271380, 46885, '<td valign="top">Nice, but way too tight. What is it?</td>', 'Nice, but way too tight. What is it?', '2005-12-23 20:36:14.000000', NULL, 1),
(1974598, 270680, 11487, '<td valign="top">Good color and pattern.  Lens flare is a bit distracting.</td>', 'Good color and pattern.  Lens flare is a bit distracting.', '2005-12-23 20:37:35.000000', NULL, 1),
(1974604, 269844, 46885, '<td valign="top">Gees, my deep sense of nature demands coming and fixing this poor chap''s beak with my bare hands! Nice one, but with subject lined up in a sinngle plane I''d like to see all areas sharp and the beak with the drop certainly looses out here.</td>', 'Gees, my deep sense of nature demands coming and fixing this poor chap''s beak with my bare hands! Nice one, but with subject lined up in a sinngle plane I''d like to see all areas sharp and the beak with the drop certainly looses out here.', '2005-12-23 20:39:21.000000', NULL, 1),
(1974607, 270625, 46885, '<td valign="top">It is. How boring.</td>', 'It is. How boring.', '2005-12-23 20:39:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1974612, 270979, 46885, '<td valign="top">Is it just me or does anyone else think of supermodels? Same rather befuddled look, a few nice strands of brown hair dropping and an elegant elongated face. This one doesn''t snort and that''s a clear advantage.</td>', 'Is it just me or does anyone else think of supermodels? Same rather befuddled look, a few nice strands of brown hair dropping and an elegant elongated face. This one doesn''t snort and that''s a clear advantage.', '2005-12-23 20:42:22.000000', NULL, 1),
(1974615, 270251, 46885, '<td valign="top">Nice dof, colours and composition, shame about the mushroom - it seems utterly inedible and so clashes with the warm and comfy feel of the picture.</td>', 'Nice dof, colours and composition, shame about the mushroom - it seems utterly inedible and so clashes with the warm and comfy feel of the picture.', '2005-12-23 20:43:21.000000', NULL, 1),
(1974619, 270450, 46885, '<td valign="top">Wicked. I love the conflict of comfy and warm orange with the desolation of the matchstick. A bit less centre-feel would improve it even further.</td>', 'Wicked. I love the conflict of comfy and warm orange with the desolation of the matchstick. A bit less centre-feel would improve it even further.', '2005-12-23 20:44:52.000000', NULL, 1),
(1974620, 271152, 46885, '<td valign="top">Nice idea, but I would actually want this picture to be sharp all the way.</td>', 'Nice idea, but I would actually want this picture to be sharp all the way.', '2005-12-23 20:46:30.000000', NULL, 1),
(1974629, 270481, 46885, '<td valign="top">It didn''t say ''Blur all the way'', it said shallow dof... Nice feel, thou</td>', 'It didn''t say ''Blur all the way'', it said shallow dof... Nice feel, thou', '2005-12-23 20:49:24.000000', NULL, 1),
(1974633, 271213, 46885, '<td valign="top">There''s a very similar entry and it''s slightly ahead in terms of composition - I don''t like the horizontal banding of the image into three...</td>', 'There''s a very similar entry and it''s slightly ahead in terms of composition - I don''t like the horizontal banding of the image into three...', '2005-12-23 20:51:22.000000', NULL, 1),
(1974635, 270722, 46885, '<td valign="top">Another great idea to which shallow dof is missaplied. Great lines. Reshoot and submit to health challenge!</td>', 'Another great idea to which shallow dof is missaplied. Great lines. Reshoot and submit to health challenge!', '2005-12-23 20:52:38.000000', NULL, 1),
(1974641, 270172, 46885, '<td valign="top">Careful. Lots of it will make you teary and your creativity will get even more blurred.</td>', 'Careful. Lots of it will make you teary and your creativity will get even more blurred.', '2005-12-23 20:55:16.000000', NULL, 1),
(1974643, 270719, 46885, '<td valign="top">What a diligent boy - how neatly symmetrical is his inaccuracy!</td>', 'What a diligent boy - how neatly symmetrical is his inaccuracy!', '2005-12-23 20:56:50.000000', NULL, 1),
(1974646, 269397, 46885, '<td valign="top">Nope. There''s still plenty of unnecessary detail in it!</td>', 'Nope. There''s still plenty of unnecessary detail in it!', '2005-12-23 20:58:15.000000', NULL, 1),
(1974650, 271117, 46885, '<td valign="top">Took me a while to figure out where he is. I twisted the screen 45 degrees anti-clockwise and it suddenly became much clearer.</td>', 'Took me a while to figure out where he is. I twisted the screen 45 degrees anti-clockwise and it suddenly became much clearer.', '2005-12-23 20:59:42.000000', NULL, 1),
(1974654, 270528, 46885, '<td valign="top">Fantastic title, but the picture is way too abstract for a trade catalogue.</td>', 'Fantastic title, but the picture is way too abstract for a trade catalogue.', '2005-12-23 21:01:22.000000', NULL, 1),
(1974661, 269843, 46885, '<td valign="top">Gosh. Size does matter, but this is one turn of a screw too far. Don''t get me wrong, I like a good screw, but with this - a simple bang with a gang of nails would do better. No, seriously, the main subject seems a bit to outsized and pushing out - I would approach it without removing the eye from the frame (with that screw :)...</td>', 'Gosh. Size does matter, but this is one turn of a screw too far. Don''t get me wrong, I like a good screw, but with this - a simple bang with a gang of nails would do better. No, seriously, the main subject seems a bit to outsized and pushing out - I would approach it without removing the eye from the frame (with that screw :)...', '2005-12-23 21:07:37.000000', NULL, 1),
(1974675, 269785, 46885, '<td valign="top">Either it''s my night shift or I am slowly loosing sanity, but I imagine a few rosy-faced clerks in the City dressed in pin-striped suits. Very nice. A bit deeper dof on the main pencil would be appreciated.</td>', 'Either it''s my night shift or I am slowly loosing sanity, but I imagine a few rosy-faced clerks in the City dressed in pin-striped suits. Very nice. A bit deeper dof on the main pencil would be appreciated.', '2005-12-23 21:19:59.000000', NULL, 1),
(1974679, 270876, 46885, '<td valign="top">Well, if that''s the user who is going to insert the card themselves, then the PCI connector (I hope you''re not playing with some old ISA junk for I can''t well see the end of it) is of importance too. A strange choice of subject, but quite well-executed.</td>', 'Well, if that''s the user who is going to insert the card themselves, then the PCI connector (I hope you''re not playing with some old ISA junk for I can''t well see the end of it) is of importance too. A strange choice of subject, but quite well-executed.', '2005-12-23 21:24:25.000000', NULL, 1),
(1974681, 269094, 46885, '<td valign="top">Nice. A bit cheesy with colouring, but quite good as far as dof is concerned.</td>', 'Nice. A bit cheesy with colouring, but quite good as far as dof is concerned.', '2005-12-23 21:25:10.000000', NULL, 1),
(1974696, 270987, 29906, '<td valign="top">As far DOF the shot definitely qualifies, but I am scoring this high for the humor factor .. 9</td>', 'As far DOF the shot definitely qualifies, but I am scoring this high for the humor factor .. 9', '2005-12-23 21:33:05.000000', NULL, 1),
(1974697, 270716, 29906, '<td valign="top">Awww how cute .. 9</td>', 'Awww how cute .. 9', '2005-12-23 21:33:18.000000', NULL, 1),
(1974699, 271000, 29906, '<td valign="top">The shot is excellent, the colors are amazing, great contrast, nice DOF, I hate those feets in the background, I wish it had even shallower DOF, 9</td>', 'The shot is excellent, the colors are amazing, great contrast, nice DOF, I hate those feets in the background, I wish it had even shallower DOF, 9', '2005-12-23 21:35:33.000000', NULL, 1),
(1974700, 271332, 41522, '<td valign="top">That''s a pretty impressive tiny sliver of focus!!!  Good work on this.</td>', 'That''s a pretty impressive tiny sliver of focus!!!  Good work on this.', '2005-12-23 21:36:38.000000', NULL, 1),
(1974702, 271271, 29906, '<td valign="top">Nice title .. The shot could''ve been more impressive if the focus was on the front part of the splash instead of the rear of it.</td>', 'Nice title .. The shot could''ve been more impressive if the focus was on the front part of the splash instead of the rear of it.', '2005-12-23 21:37:25.000000', NULL, 1),
(1974734, 271325, 41522, '<td valign="top">Nice subject matter, good work on the Shallow DOF.  Nicely composed.</td>', 'Nice subject matter, good work on the Shallow DOF.  Nicely composed.', '2005-12-23 22:07:13.000000', NULL, 1),
(1974772, 270680, 47020, '<td valign="top">wow, who knew such a simple thing could look so very beautiful?  Very very nice.</td>', 'wow, who knew such a simple thing could look so very beautiful?  Very very nice.', '2005-12-23 22:36:51.000000', NULL, 1),
(1974777, 271266, 47020, '<td valign="top">excellent premise and setup.  Nice shot.</td>', 'excellent premise and setup.  Nice shot.', '2005-12-23 22:39:43.000000', NULL, 1),
(1974816, 270130, 49672, '<td valign="top">You cheated - those aren''t reall bulls-eyes!  The photo is great, though.</td>', 'You cheated - those aren''t reall bulls-eyes!  The photo is great, though.', '2005-12-23 23:12:30.000000', NULL, 1),
(1974893, 271104, 25635, '<td valign="top">Umm...that is REALLY scary...</td>', 'Umm...that is REALLY scary...', '2005-12-23 23:54:41.000000', NULL, 1),
(1974905, 271227, 25635, '<td valign="top">Creepy...period.</td>', 'Creepy...period.', '2005-12-23 23:59:35.000000', NULL, 1),
(1974988, 270777, 22734, '<td valign="top">Very nice use of the principle to marry name and image.</td>', 'Very nice use of the principle to marry name and image.', '2005-12-24 01:02:06.000000', NULL, 1),
(1974990, 270490, 22734, '<td valign="top">Simply awesome and resembling a musical sunrise!</td>', 'Simply awesome and resembling a musical sunrise!', '2005-12-24 01:04:18.000000', NULL, 1),
(1974991, 271334, 22734, '<td valign="top">Certainly interesting. The bokeh eyes are a rip.</td>', 'Certainly interesting. The bokeh eyes are a rip.', '2005-12-24 01:05:20.000000', NULL, 1),
(1974992, 270721, 22734, '<td valign="top">A divine capture. Bumping up.</td>', 'A divine capture. Bumping up.', '2005-12-24 01:06:40.000000', NULL, 1),
(1974994, 270505, 22734, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2005-12-24 01:11:31.000000', NULL, 1),
(1975076, 270780, 30364, '<td valign="top">An unusual photograph.  Interesting, too ... in spite of the prosaic subject matter.  The image stands out particularly well in this challenge because it''s actually about something (i.e. it has a subject) and uses depth of field for effect, whereas all but a tiny handful of the other entries are about nothing, and use depth of field as the subject.  8.</td>', 'An unusual photograph.  Interesting, too ... in spite of the prosaic subject matter.  The image stands out particularly well in this challenge because it''s actually about something (i.e. it has a subject) and uses depth of field for effect, whereas all but a tiny handful of the other entries are about nothing, and use depth of field as the subject.  8.', '2005-12-24 02:44:59.000000', NULL, 1),
(1975079, 269505, 30364, '<td valign="top">Very clever to use the yellow/green apple as the in-focus subject, and the reds as the out-of-focus.  The depth of field is employed with assurance and purpose here, but the beautiful composition and lighting should not be overlooked as well.  Very nice photograph.  8.</td>', 'Very clever to use the yellow/green apple as the in-focus subject, and the reds as the out-of-focus.  The depth of field is employed with assurance and purpose here, but the beautiful composition and lighting should not be overlooked as well.  Very nice photograph.  8.', '2005-12-24 02:48:09.000000', NULL, 1),
(1975086, 270424, 30364, '<td valign="top">Effective use of depth of field for two purposes.  First, to isolate an essential aspect of the subject.  Second, to establish a contextual mood that complements the statement you''re making about that subject.  A very nice, sophisticated work.  Hope it doesn''t get overlooked in favour of the merely pretty.   8.</td>', 'Effective use of depth of field for two purposes.  First, to isolate an essential aspect of the subject.  Second, to establish a contextual mood that complements the statement you''re making about that subject.  A very nice, sophisticated work.  Hope it doesn''t get overlooked in favour of the merely pretty.   8.', '2005-12-24 02:53:38.000000', NULL, 1),
(1975094, 269260, 30364, '<td valign="top">This will score very high, I expect.  However, I''m prepared to be unpopular and suggest that the employment of depth of field achieves little more here than would holding a bit of contrasting paper behind the subject.  I mean the out-of-focus background has no contextual purpose.  It is a technically proficient photograph, and the falling drop of course provides just the wow factor required for DPC success.  It''s just that I feel you''ve used depth of field as a drunk uses a lamp post ... for support, rather than for illumination.  6.</td>', 'This will score very high, I expect.  However, I''m prepared to be unpopular and suggest that the employment of depth of field achieves little more here than would holding a bit of contrasting paper behind the subject.  I mean the out-of-focus background has no contextual purpose.  It is a technically proficient photograph, and the falling drop of course provides just the wow factor required for DPC success.  It''s just that I feel you''ve used depth of field as a drunk uses a lamp post ... for support, rather than for illumination.  6.', '2005-12-24 03:06:50.000000', NULL, 1),
(1975101, 270158, 30364, '<td valign="top">What I like about this is that the out-of-focus elements of the photograph have a definite purpose; although those two gulls are visually subordinated to the leading gull, he would be diminished without their essential supporting performances.  And that''s what I feel this challenge is really about ... using shallow depth of field to take some sort of artistic position about your subject.  Plus it''s a very unusual but interesting and challenging composition.  8.</td>', 'What I like about this is that the out-of-focus elements of the photograph have a definite purpose; although those two gulls are visually subordinated to the leading gull, he would be diminished without their essential supporting performances.  And that''s what I feel this challenge is really about ... using shallow depth of field to take some sort of artistic position about your subject.  Plus it''s a very unusual but interesting and challenging composition.  8.', '2005-12-24 03:14:00.000000', NULL, 1),
(1975107, 270717, 30364, '<td valign="top">The best of the several inevitable chess images, especially as you knew to quote Philidor.  7.</td>', 'The best of the several inevitable chess images, especially as you knew to quote Philidor.  7.', '2005-12-24 03:17:16.000000', NULL, 1),
(1975130, 269424, 30364, '<td valign="top">My first choice in this challenge.  The critical thing here is that you have used the depth of field to enhance both the look AND the meaning of your photograph, a possibility that does not appear to have occurred to those who decided that depth of field WAS the subject!  Any image of an old person shuffling by with the aid of a stick is likely to be worthy and thought-provoking in itself, but this image, which includes the old lady as the perfect reciprocal of the old man, is by comparison laden with possibilities for deeper meaning.  And of course the use of a shallow depth of field both literally AND figuratively isolates the two subjects from each other, leaving each to plot a lonely course, which presumably is the artistic point of the image.  It''s a thoughtful, confident yet quiet image.  Such a welcome change.  Bravo!  10.</td>', 'My first choice in this challenge.  The critical thing here is that you have used the depth of field to enhance both the look AND the meaning of your photograph, a possibility that does not appear to have occurred to those who decided that depth of field WAS the subject!  Any image of an old person shuffling by with the aid of a stick is likely to be worthy and thought-provoking in itself, but this image, which includes the old lady as the perfect reciprocal of the old man, is by comparison laden with possibilities for deeper meaning.  And of course the use of a shallow depth of field both literally AND figuratively isolates the two subjects from each other, leaving each to plot a lonely course, which presumably is the artistic point of the image.  It''s a thoughtful, confident yet quiet image.  Such a welcome change.  Bravo!  10.', '2005-12-24 03:45:14.000000', NULL, 1),
(1975137, 269844, 30364, '<td valign="top">This will be very popular.  It''s a nice photo of the subject, and the depth of field has removed all possible distractions.  That will be widely admired by the voters, as will the droplet of water.  <br/>I prefer those images that employ depth of field to some more ambitious artistic purpose, but that''s just me.  6.</td>', 'This will be very popular.  It''s a nice photo of the subject, and the depth of field has removed all possible distractions.  That will be widely admired by the voters, as will the droplet of water.  I prefer those images that employ depth of field to some more ambitious artistic purpose, but that''s just me.  6.', '2005-12-24 03:55:31.000000', NULL, 1),
(1975140, 271371, 17507, '<td valign="top">colors = excellent<br/>focus = excellent<br/>composition = excellent<br/>exposure = excellent<br/> <br/>this is one excellent image.</td>', 'colors = excellentfocus = excellentcomposition = excellentexposure = excellent this is one excellent image.', '2005-12-24 04:10:22.000000', NULL, 1),
(1975141, 270598, 17507, '<td valign="top">picture seems a bit dark - I think even an an Auto Levels adjustment would have really improved this image.</td>', 'picture seems a bit dark - I think even an an Auto Levels adjustment would have really improved this image.', '2005-12-24 04:11:42.000000', NULL, 1),
(1975143, 271016, 17507, '<td valign="top">very cool! did you glue the flower to a window? can''t figure how else you might have accomplished this charmingly simple and satisfying image!</td>', 'very cool! did you glue the flower to a window? can''t figure how else you might have accomplished this charmingly simple and satisfying image!', '2005-12-24 04:12:55.000000', NULL, 1),
(1975144, 271064, 17507, '<td valign="top">I guess that''s one of those stone eggs? Has a rather disturbing effect--an element that I think might adversely affect your score. (6)</td>', 'I guess that''s one of those stone eggs? Has a rather disturbing effect--an element that I think might adversely affect your score. (6)', '2005-12-24 04:15:11.000000', NULL, 1),
(1975147, 269334, 17507, '<td valign="top">nice picture - but why the black border? your image is rather high key and the stark black is distracting. I think white would have worked better. (7)</td>', 'nice picture - but why the black border? your image is rather high key and the stark black is distracting. I think white would have worked better. (7)', '2005-12-24 04:18:32.000000', NULL, 1),
(1975148, 269211, 17507, '<td valign="top">I guess the thing being reflected is a tree - can''t be sure - but at first it looked like a dead ant or some other desiccated insect plastered to the glass.</td>', 'I guess the thing being reflected is a tree - can''t be sure - but at first it looked like a dead ant or some other desiccated insect plastered to the glass.', '2005-12-24 04:19:51.000000', NULL, 1),
(1975150, 269610, 17507, '<td valign="top">I think that cropping off a bit at the bottom, making the aspect ratio maybe 1.2:1 or 1.4:1, would tighten up this image and keep the viewer''s attention on the left somewhat better. including the far edge of the ribbon in the lower right is an invitation for the eye to wander, because it''s such an isolated shape, and that takes the viewer straight away from the upper left, where all the visual interest is. I think this is a really good image - the unusual palette of greys and lavenders is soothing - but the presentation is a bit off. presentation is essential! (6)</td>', 'I think that cropping off a bit at the bottom, making the aspect ratio maybe 1.2:1 or 1.4:1, would tighten up this image and keep the viewer''s attention on the left somewhat better. including the far edge of the ribbon in the lower right is an invitation for the eye to wander, because it''s such an isolated shape, and that takes the viewer straight away from the upper left, where all the visual interest is. I think this is a really good image - the unusual palette of greys and lavenders is soothing - but the presentation is a bit off. presentation is essential! (6)', '2005-12-24 04:25:48.000000', NULL, 1),
(1975151, 270251, 17507, '<td valign="top">sweet picture, I love fresh pizza toppings</td>', 'sweet picture, I love fresh pizza toppings', '2005-12-24 04:26:10.000000', NULL, 1),
(1975152, 271181, 17507, '<td valign="top">eeeeeeeeeeeeeeeeeeeeeeeeeeew &gt;_&lt;</td>', 'eeeeeeeeeeeeeeeeeeeeeeeeeeew >_<', '2005-12-24 04:26:27.000000', NULL, 1),
(1975154, 271332, 17507, '<td valign="top">now that''s a shallow DOF! this looks like f/1.4 or even larger!</td>', 'now that''s a shallow DOF! this looks like f/1.4 or even larger!', '2005-12-24 04:27:22.000000', NULL, 1),
(1975155, 270777, 17507, '<td valign="top">good thing I get to spin the barrel before I pull the trigger!!</td>', 'good thing I get to spin the barrel before I pull the trigger!!', '2005-12-24 04:27:59.000000', NULL, 1),
(1975156, 270680, 49870, '<td valign="top">Finally someone who got it right and took a great photograph!</td>', 'Finally someone who got it right and took a great photograph!', '2005-12-24 04:31:18.000000', NULL, 1),
(1975157, 270366, 17507, '<td valign="top">wow, I''ve never seen a medical marijuana bottle label before... how cute...<br/> <br/>I just figured out that the yellowish glob is the bowl of a pipe. If the bowl were in the focal plane, this would be much stronger.<br/> <br/>the focal plane should probably also have been a bit closer to the camera, about on the "U" in "MEDICAL USE ONLY." Remember, the range of acceptable DOF around the actual point of focus is 1/3 coming toward the camera and 2/3 going away - so keep the focus somewhat closer than in the middle of the area that needs to be sharp.</td>', 'wow, I''ve never seen a medical marijuana bottle label before... how cute... I just figured out that the yellowish glob is the bowl of a pipe. If the bowl were in the focal plane, this would be much stronger. the focal plane should probably also have been a bit closer to the camera, about on the "U" in "MEDICAL USE ONLY." Remember, the range of acceptable DOF around the actual point of focus is 1/3 coming toward the camera and 2/3 going away - so keep the focus somewhat closer than in the middle of the area that needs to be sharp.', '2005-12-24 04:31:26.000000', NULL, 1),
(1975159, 270989, 11487, '<td valign="top">Great color and use of DOF.</td>', 'Great color and use of DOF.', '2005-12-24 04:32:56.000000', NULL, 1),
(1975162, 270430, 17507, '<td valign="top">the tone and color of the wood are attractive. DOF seems to be a secondary element to the picture; the sharpness of the reflection is not particularly important. i think the more difficult technical achievement would have been to keep the reflection in crisp focus, which is why I think this is a poor choice of submission for this challenge. to me, this image does not reflect thoughtful, deliberate control over depth of field.</td>', 'the tone and color of the wood are attractive. DOF seems to be a secondary element to the picture; the sharpness of the reflection is not particularly important. i think the more difficult technical achievement would have been to keep the reflection in crisp focus, which is why I think this is a poor choice of submission for this challenge. to me, this image does not reflect thoughtful, deliberate control over depth of field.', '2005-12-24 04:36:25.000000', NULL, 1),
(1975164, 270910, 17507, '<td valign="top">great choice of subject for a photo shoot! needlework is rarely seen (at least on DPC); this picture is made all the more charming by being composed of simple everyday objects.</td>', 'great choice of subject for a photo shoot! needlework is rarely seen (at least on DPC); this picture is made all the more charming by being composed of simple everyday objects.', '2005-12-24 04:37:57.000000', NULL, 1),
(1975167, 269049, 49870, '<td valign="top">Maybe</td>', 'Maybe', '2005-12-24 04:42:14.000000', NULL, 1),
(1975168, 271266, 11487, '<td valign="top">Great color and rythum.  A bit hard to isolate the blue M&amp;M when somw of the orange ones are incfocus.  Color is used more for isolation.</td>', 'Great color and rythum.  A bit hard to isolate the blue M&M when somw of the orange ones are incfocus.  Color is used more for isolation.', '2005-12-24 04:43:17.000000', NULL, 1),
(1975171, 270835, 49870, '<td valign="top">Very Intense, I like the concept : )</td>', 'Very Intense, I like the concept : )', '2005-12-24 04:44:53.000000', NULL, 1),
(1975173, 269825, 11487, '<td valign="top">A lower field of view and tighter angle may have made this a stronger image.</td>', 'A lower field of view and tighter angle may have made this a stronger image.', '2005-12-24 04:47:51.000000', NULL, 1),
(1975174, 269844, 11487, '<td valign="top">Sharp focus on the subject and isolation from the background.  May be a lottle less neck would have been a stronger composition.  Nice job.</td>', 'Sharp focus on the subject and isolation from the background.  May be a lottle less neck would have been a stronger composition.  Nice job.', '2005-12-24 04:50:17.000000', NULL, 1),
