(1980969, 270900, 43410, '<td valign="top">great shot, wish its tail wasn''t cut off. beautiful done though.  7</td>', 'great shot, wish its tail wasn''t cut off. beautiful done though.  7', '2005-12-27 11:32:38.000000', NULL, 1),
(1980984, 271213, 43410, '<td valign="top">now that''s some depth of field control right there, wow...great job :)</td>', 'now that''s some depth of field control right there, wow...great job :)', '2005-12-27 11:40:31.000000', NULL, 1),
(1981032, 269672, 43410, '<td valign="top">this is amazing, great thirds composition, love the perfect focus on the humorous center.  great addition to the frustration with the broken pencil.  great job, hopefully this one will make a ribbon.  10!</td>', 'this is amazing, great thirds composition, love the perfect focus on the humorous center.  great addition to the frustration with the broken pencil.  great job, hopefully this one will make a ribbon.  10!', '2005-12-27 12:12:13.000000', NULL, 1),
(1981035, 270638, 43410, '<td valign="top">very nice. 7</td>', 'very nice. 7', '2005-12-27 12:14:48.000000', NULL, 1),
(1981054, 271089, 40868, '<td valign="top">The surface distracts from an overall good picture.</td>', 'The surface distracts from an overall good picture.', '2005-12-27 12:27:14.000000', NULL, 1),
(1981100, 269424, 35802, '<td valign="top">I love the emotion this evokes, its a wonderful capture, however the focus could be sharper in the man, as you likely know.  Good Job, Great Composition.</td>', 'I love the emotion this evokes, its a wonderful capture, however the focus could be sharper in the man, as you likely know.  Good Job, Great Composition.', '2005-12-27 12:52:32.000000', NULL, 1),
(1981101, 270515, 35802, '<td valign="top">Interesting  subject.</td>', 'Interesting  subject.', '2005-12-27 12:52:55.000000', NULL, 1),
(1981103, 270443, 35802, '<td valign="top">Beautiful Portrait.  Beautiful Model.  Great Lighting. 10</td>', 'Beautiful Portrait.  Beautiful Model.  Great Lighting. 10', '2005-12-27 12:53:57.000000', NULL, 1),
(1981104, 271336, 35802, '<td valign="top">Beautiful.  Focus could be a tad crisper.  But still a great shot.</td>', 'Beautiful.  Focus could be a tad crisper.  But still a great shot.', '2005-12-27 12:54:37.000000', NULL, 1),
(1981109, 270506, 37015, '<td valign="top">I think the DOF doesn''t do enough here to isolate the foreground.  Also, the shutter speed should''ve been a been faster to capture the water.</td>', 'I think the DOF doesn''t do enough here to isolate the foreground.  Also, the shutter speed should''ve been a been faster to capture the water.', '2005-12-27 12:56:21.000000', NULL, 1),
(1981119, 271382, 37015, '<td valign="top">It looks like the cap is a bit out of focus and I would''ve liked to see the cap twisted so that it''s easier to read.</td>', 'It looks like the cap is a bit out of focus and I would''ve liked to see the cap twisted so that it''s easier to read.', '2005-12-27 13:06:57.000000', NULL, 1),
(1981161, 271053, 37015, '<td valign="top">I think the DOF could just a tad bit shallower.  Otherwise, great lighting, great composition, great capture.</td>', 'I think the DOF could just a tad bit shallower.  Otherwise, great lighting, great composition, great capture.', '2005-12-27 13:38:53.000000', NULL, 1),
(1981205, 270732, 37015, '<td valign="top">I think a bit more could''ve been done with the lighting.  However, I do like the idea and the DOF.</td>', 'I think a bit more could''ve been done with the lighting.  However, I do like the idea and the DOF.', '2005-12-27 14:14:20.000000', NULL, 1),
