INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1981566, 269535, 47933, '<td valign="top">Good job. Nicely done!</td>', 'Good job. Nicely done!', '2005-12-27 15:56:19.000000', NULL, 1),
(1981567, 269424, 47933, '<td valign="top">Great capture. A++</td>', 'Great capture. A++', '2005-12-27 15:56:47.000000', NULL, 1),
(1981569, 270543, 49876, '<td valign="top">nice image</td>', 'nice image', '2005-12-27 15:56:56.000000', NULL, 1),
(1981570, 271376, 49876, '<td valign="top">nice image</td>', 'nice image', '2005-12-27 15:57:11.000000', NULL, 1),
(1981571, 269672, 47933, '<td valign="top">Good imagination. Nice job!</td>', 'Good imagination. Nice job!', '2005-12-27 15:57:16.000000', NULL, 1),
(1981572, 269812, 49876, '<td valign="top">nice image</td>', 'nice image', '2005-12-27 15:57:18.000000', NULL, 1),
(1981573, 271149, 49876, '<td valign="top">nice image</td>', 'nice image', '2005-12-27 15:57:35.000000', NULL, 1),
(1981575, 271171, 47933, '<td valign="top">I like it. Color, composition, DOF - all good.</td>', 'I like it. Color, composition, DOF - all good.', '2005-12-27 15:58:28.000000', NULL, 1),
(1981611, 270415, 47912, '<td valign="top">Beautiful job, the DOF is perfect for this compostion.</td>', 'Beautiful job, the DOF is perfect for this compostion.', '2005-12-27 16:08:17.000000', NULL, 1),
(1981659, 270807, 40819, '<td valign="top">Seems like too much USM.otherwise nice macro</td>', 'Seems like too much USM.otherwise nice macro', '2005-12-27 16:17:43.000000', NULL, 1),
(1981662, 271339, 40819, '<td valign="top">This is a great shot, not macro and great shallow DOF. NIce B&amp;W  too.</td>', 'This is a great shot, not macro and great shallow DOF. NIce B&W  too.', '2005-12-27 16:18:36.000000', NULL, 1),
(1981667, 269429, 40819, '<td valign="top">Excellent and emotive.</td>', 'Excellent and emotive.', '2005-12-27 16:19:33.000000', NULL, 1),
(1981708, 270443, 47151, '<td valign="top">such a wonderful photo. it makes me see how she feels about rainy days</td>', 'such a wonderful photo. it makes me see how she feels about rainy days', '2005-12-27 16:33:49.000000', NULL, 1),
(1981721, 270825, 47912, '<td valign="top">Very cool</td>', 'Very cool', '2005-12-27 16:44:42.000000', NULL, 1),
(1981740, 270780, 37015, '<td valign="top">I''ve passed this image up a couple time since I was undecided about it each time.  I think that allow the DOF is good (actually, it could be a tad more shallow) and the lighting is fine, there''s too much of the luggage taking up the frame, so it''s hard for me to get a sense of the them being left behind.  The way it''s composed, it feels cramped, giving me more of a sense of urgency, rather than lonliness, i.e. luggage sitting there by itself.</td>', 'I''ve passed this image up a couple time since I was undecided about it each time.  I think that allow the DOF is good (actually, it could be a tad more shallow) and the lighting is fine, there''s too much of the luggage taking up the frame, so it''s hard for me to get a sense of the them being left behind.  The way it''s composed, it feels cramped, giving me more of a sense of urgency, rather than lonliness, i.e. luggage sitting there by itself.', '2005-12-27 16:56:11.000000', NULL, 1),
(1981741, 270508, 47151, '<td valign="top">too dark for my taste. The light from the window caused your problem. try taking the pic from a diffrent angle or wait till night fall and see if that helps.</td>', 'too dark for my taste. The light from the window caused your problem. try taking the pic from a diffrent angle or wait till night fall and see if that helps.', '2005-12-27 16:56:33.000000', NULL, 1),
(1981752, 270716, 37015, '<td valign="top">DOF is not very apparent in this picture.  I think more could''ve been done with the background to make it more interesting.  As it is, it seems very much like a snapshot.</td>', 'DOF is not very apparent in this picture.  I think more could''ve been done with the background to make it more interesting.  As it is, it seems very much like a snapshot.', '2005-12-27 17:07:23.000000', NULL, 1),
(1981756, 271117, 37015, '<td valign="top">I like the DOF and the lighting a lot in this image.  I think, however, that getting the feet into the shot would''ve made it more apparent that he''s dangling from a peg on a wall.  I think moving the shot over to the left or pulling back a bit would''ve achieved this.</td>', 'I like the DOF and the lighting a lot in this image.  I think, however, that getting the feet into the shot would''ve made it more apparent that he''s dangling from a peg on a wall.  I think moving the shot over to the left or pulling back a bit would''ve achieved this.', '2005-12-27 17:12:34.000000', NULL, 1),
(1981788, 271105, 44944, '<td valign="top">Using the second, third or fourth candle-light would give more the impression the shallow DOF: in that case you can see the beginning and the end of the area in-focus. To be honest: I did not use this aspect in my own picture for this challenge :-(</td>', 'Using the second, third or fourth candle-light would give more the impression the shallow DOF: in that case you can see the beginning and the end of the area in-focus. To be honest: I did not use this aspect in my own picture for this challenge :-(', '2005-12-27 17:37:39.000000', NULL, 1),
(1981803, 271026, 47912, '<td valign="top">Very nice job.</td>', 'Very nice job.', '2005-12-27 17:48:24.000000', NULL, 1),
(1981804, 271171, 47912, '<td valign="top">Fantastic job.</td>', 'Fantastic job.', '2005-12-27 17:49:44.000000', NULL, 1),
(1981836, 271152, 37015, '<td valign="top">Good setup and great composition and great lighting.  However, I think DOF could''ve been a bit more shallow.  I''m still rating this pretty high, though. :)</td>', 'Good setup and great composition and great lighting.  However, I think DOF could''ve been a bit more shallow.  I''m still rating this pretty high, though. :)', '2005-12-27 18:11:41.000000', NULL, 1),
(1981850, 271365, 37015, '<td valign="top">Very interesting shot - I like it!  I''m not sure why though...they''re just boots.  I guess all the right elements are there: good lighting, composition, and DOF.  Excellent.</td>', 'Very interesting shot - I like it!  I''m not sure why though...they''re just boots.  I guess all the right elements are there: good lighting, composition, and DOF.  Excellent.', '2005-12-27 18:18:28.000000', NULL, 1),
(1981852, 271228, 37015, '<td valign="top">I think moving the DOF back a bit to include the stem would''ve helped this picture, in my opinion.  Also, a white, as opposed to gray background would''ve also been nice.</td>', 'I think moving the DOF back a bit to include the stem would''ve helped this picture, in my opinion.  Also, a white, as opposed to gray background would''ve also been nice.', '2005-12-27 18:19:51.000000', NULL, 1),
(1981854, 271369, 37015, '<td valign="top">Nice DOF and composition.  However, I would''ve liked to see a bit more light on both roses.</td>', 'Nice DOF and composition.  However, I would''ve liked to see a bit more light on both roses.', '2005-12-27 18:20:46.000000', NULL, 1),
(1981878, 269825, 37015, '<td valign="top">The DOF is great in this picture!  I like the refraction of one glass by the other.  The transition from gray to the white background is great.</td>', 'The DOF is great in this picture!  I like the refraction of one glass by the other.  The transition from gray to the white background is great.', '2005-12-27 18:30:31.000000', NULL, 1),
(1981890, 269189, 37015, '<td valign="top">Although it''s a good and interesting capture, the DOF isn''t very apparent in this one.</td>', 'Although it''s a good and interesting capture, the DOF isn''t very apparent in this one.', '2005-12-27 18:34:19.000000', NULL, 1),
(1981894, 271246, 4226, '<td valign="top">From even an ant''s view I think the closest object would be the most in focus and not something further away.. .</td>', 'From even an ant''s view I think the closest object would be the most in focus and not something further away.. .', '2005-12-27 18:35:17.000000', NULL, 1),
(1981900, 270762, 37015, '<td valign="top">Not much to say about this picture.  Great DOF and composition.  Great job on making barbed wire interesting. :)</td>', 'Not much to say about this picture.  Great DOF and composition.  Great job on making barbed wire interesting. :)', '2005-12-27 18:36:12.000000', NULL, 1),
(1981901, 270564, 4226, '<td valign="top">the border seems too heavy for the image.. 6</td>', 'the border seems too heavy for the image.. 6', '2005-12-27 18:36:15.000000', NULL, 1),
(1981903, 271334, 4226, '<td valign="top">the eyes really look spooky here :)  <br/>Nice idea 7</td>', 'the eyes really look spooky here :)  Nice idea 7', '2005-12-27 18:37:24.000000', NULL, 1),
(1981974, 270564, 30208, '<td valign="top">Nice picture but the border is too distracting.</td>', 'Nice picture but the border is too distracting.', '2005-12-27 19:10:13.000000', NULL, 1),
