(1982216, 270053, 41802, '<td valign="top">Sweet! Awesome work !</td>', 'Sweet! Awesome work !', '2005-12-27 20:41:04.000000', NULL, 1),
(1982217, 270430, 48982, '<td valign="top">Nicely composed.  It almost feels desaturated which gives it a nice timeless quality.  I would love to have taken this one.  It appeals to my personal aesthetic.</td>', 'Nicely composed.  It almost feels desaturated which gives it a nice timeless quality.  I would love to have taken this one.  It appeals to my personal aesthetic.', '2005-12-27 20:41:08.000000', NULL, 1),
